import re
import subprocess
from flask import Flask, request, jsonify

app = Flask(__name__)


def _split_flags(filter_flags):
    """Split a ps flags string into a list of tokens."""
    if not filter_flags:
        return []
    return filter_flags.split()


def _run_ps(flags):
    """Run ps with the given flags and return the raw output lines."""
    cmd = ["ps"] + flags
    result = subprocess.run(
        cmd,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
    )
    if result.returncode != 0:
        raise RuntimeError(result.stderr.strip() or "ps command failed")
    return result.stdout.splitlines()


def _find_pid_column(header_line):
    """Locate the column index of the PID field in the ps header."""
    # ps separates columns by whitespace; find the token 'PID'
    tokens = header_line.split()
    for idx, token in enumerate(tokens):
        if token.upper() == "PID":
            return idx
    return None


def _parse_processes(lines):
    """Parse ps output lines into (pid, full_line) tuples."""
    processes = []
    if not lines:
        return processes

    header = lines[0]
    pid_idx = _find_pid_column(header)

    for line in lines[1:]:
        if not line.strip():
            continue
        if pid_idx is not None:
            tokens = line.split(None, pid_idx + 1)
            if len(tokens) > pid_idx:
                pid_token = tokens[pid_idx]
                try:
                    pid = int(pid_token)
                except ValueError:
                    continue
                processes.append((pid, line))
        else:
            # Fallback: try first token as PID
            tokens = line.split(None, 1)
            if tokens:
                try:
                    pid = int(tokens[0])
                except ValueError:
                    continue
                processes.append((pid, line))
    return processes


@app.route("/monitor/commands", methods=["POST"])
def monitor_commands():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return jsonify({"code": 400, "message": "Invalid JSON body"}), 400

    command_regex = data.get("command_regex")
    if not isinstance(command_regex, str) or not command_regex:
        return jsonify({"code": 400, "message": "command_regex is required"}), 400

    filter_flags = data.get("filter_flags", "")
    if filter_flags is None:
        filter_flags = ""
    if not isinstance(filter_flags, str):
        return jsonify({"code": 400, "message": "filter_flags must be a string"}), 400

    try:
        pattern = re.compile(command_regex)
    except re.error as exc:
        return jsonify({"code": 400, "message": f"Invalid regex: {exc}"}), 400

    flags = _split_flags(filter_flags)

    try:
        lines = _run_ps(flags)
    except FileNotFoundError:
        return jsonify({"code": 500, "message": "ps command not available"}), 500
    except RuntimeError as exc:
        return jsonify({"code": 500, "message": str(exc)}), 500

    try:
        processes = _parse_processes(lines)
    except Exception as exc:  # noqa: BLE001
        return jsonify({"code": 500, "message": f"Failed to parse ps output: {exc}"}), 500

    results = []
    for pid, full_line in processes:
        if pattern.search(full_line):
            results.append({"processId": pid, "processString": full_line})

    return jsonify(results), 200


@app.errorhandler(404)
def not_found(_err):
    return jsonify({"code": 404, "message": "Not found"}), 404


@app.errorhandler(405)
def method_not_allowed(_err):
    return jsonify({"code": 405, "message": "Method not allowed"}), 405


@app.errorhandler(500)
def internal_error(_err):
    return jsonify({"code": 500, "message": "Internal server error"}), 500


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000)
